ruleBookInfo.tocUrl:
@js:
l = Math.floor(('{{$.chapterTotalNum}}')/50);
list=[];
for(i=0;i<=l;i++){            
  link_Urlpath = "/api/read/directory";
  link_Params = {
		"bookId": java.put("bookId","{{$.bookId}}"),
	 "chapterNum": (i*50+1),
		"isNext": "1",
		"is_ad_version": "1",
		"sort": "asc"
	};
  url = GetUrl(link_Params,link_Urlpath);
  list.push(url);
}
java.put("list",list.slice(1).join('@'));

list[0]

